<?php $eyebrow=get_field('eyebrow');$title=get_field('title');$description=get_field('description');$sponsors=get_field('sponsors'); ?><section class="sariyah-sponsors"><div class="sariyah-container"><div class="sariyah-sponsors__heading"><?php if($eyebrow): ?><p class="sariyah-section-eyebrow"><?php echo esc_html($eyebrow); ?></p><?php endif; ?><?php if($title): ?><h2><?php echo esc_html($title); ?></h2><?php endif; ?><?php if($description): ?><p><?php echo esc_html($description); ?></p><?php endif; ?></div><?php if(is_array($sponsors)&&$sponsors): ?><div class="sariyah-sponsors__grid"><?php foreach($sponsors as $sponsor): $logo=$sponsor['logo']??null;$url=$sponsor['url']??''; ?><div class="sariyah-sponsor"><?php if($url): ?><a href="<?php echo esc_url($url); ?>" target="_blank" rel="noopener noreferrer"><?php endif; ?><?php if(is_array($logo)&&!empty($logo['ID'])): ?><?php echo wp_get_attachment_image((int)$logo['ID'],'medium',false,array('loading'=>'lazy')); ?><?php elseif(!empty($sponsor['name'])): ?><span><?php echo esc_html($sponsor['name']); ?></span><?php endif; ?><?php if($url): ?></a><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></div></section>